<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserAcceptedTermsOfUse\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\UserAcceptedTermsOfUse\Domain\ValueObject\UserAcceptedTermsOfUseConditionsVO;
use Civi\Lughauth\Features\Access\TenantTermsOfUse\Domain\TenantTermsOfUseRef;

trait UserAcceptedTermsOfUseConditionsAttributeHolder
{
    protected UserAcceptedTermsOfUseConditionsVO|TenantTermsOfUseRef|null $conditions = null;
    protected bool $conditionsAssigned = false;

    public function getConditionsOrCurrent(UserAcceptedTermsOfUseConditionsVO $conditions): UserAcceptedTermsOfUseConditionsVO
    {
        if ($this->conditionsAssigned) {
            \assert(null !== $this->conditions);
            return UserAcceptedTermsOfUseConditionsVO::from($this->conditions);
        } else {
            return $conditions;
        }
    }
    public function conditionsTryBuildInitial(ConstraintFailList $error): ?UserAcceptedTermsOfUseConditionsVO
    {
        return  UserAcceptedTermsOfUseConditionsVO::tryFrom($this->conditionsAssigned ? $this->conditions : null, $error);
    }
    public function conditions(UserAcceptedTermsOfUseConditionsVO|TenantTermsOfUseRef $conditions): static
    {
        $this->conditions = $conditions;
        $this->conditionsAssigned = true;
        return $this;
    }
    public function getConditions(): ?TenantTermsOfUseRef
    {
        return $this->conditions instanceof UserAcceptedTermsOfUseConditionsVO ? $this->conditions->value() : $this->conditions;
    }
    public function isConditionsAssigned(): bool
    {
        return $this->conditionsAssigned;
    }
    public function writeConditionsTo(mixed $att): void
    {
        if ($this->conditionsAssigned) {
            \assert(null !== $this->conditions);
            $att->conditions($this->conditions);
        }
    }
    public function readConditionsFrom(mixed $att): void
    {
        if ($att->isConditionsAssigned()) {
            $conditions = $att->getConditions();
            \assert(null !== $conditions);
            $this->conditions($conditions);
        }
    }
    public function unsetConditions(): static
    {
        $this->conditionsAssigned = false;
        return $this;
    }
    protected function withDefaultConditions(): void
    {
    }
    protected function withAssertedConditionsRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->conditionsAssigned = $this->conditionsAssigned) {
            $value->conditions = UserAcceptedTermsOfUseConditionsVO::tryFrom($this->conditions, $errorsList);
        }
    }
}
